def start(self, refresh: bool = False) -> None:
    \"\"\"Start live rendering display.\"\"\"
    with self._lock:
        if not self._started:
            return

        renderable = self.get_renderable() if self._get_renderable else self._renderable
        if renderable is None:
            self.stop()
            return

        if not self.console.set_live(self):
            self._nested = True
            return

        if self._screen:
            self._alt_screen = self.console.set_alt_screen(True)
        self.console.show_cursor(False)
        self._enable_redirect_io()
        self.console.push_render_hook(self)
        if refresh:
            try:
                self.refresh()
            except Exception:
                # If refresh fails, we want to stop the redirection of sys.stderr,
                # so the error stacktrace is properly displayed in the terminal.\n                    # (or, if the code that calls Rich captures the exception and wants to display something,\n                    # let this be displayed in the terminal).\n                    self.stop()\n                    raise
        if self.auto_refresh:
            self._refresh_thread = _RefreshThread(self, self.refresh_per_second)
            self._refresh_thread.start()

